SKquests_GuideES.Alliance[1] = {title = [[1-5 Northshire Valley — Circuito 1]], text = [[
01) Toma estas 7 misiones cerca de Ayudante de alguacil Willem (48.2, 42.9): "A Threat Within", "Kobold Camp Cleanup", "Wolves Across the Border", "Eagan Peltskinner", "Investigate Echo Ridge", "Skirmish at Echo Ridge", "Report to Goldshire".
02) Haz "A Threat Within" (48.9, 41.6): Habla con el alguacil McBride.
03) Haz "Kobold Camp Cleanup" (48.9, 41.6): Mata 10 alimañas kobold y ve a hablar con el alguacil McBride.
04) Haz "Investigate Echo Ridge" (48.9, 41.6): Mata 10 obreros kobold y ve a hablar con el alguacil McBride.
05) Haz "Skirmish at Echo Ridge" (48.9, 41.6): Mata 12 peones kobold y ve a hablar con el alguacil McBride a la Abadía de Villanorte.
06) Haz "Wolves Across the Border" (48.9, 40.2): Lleva 8 piezas de carne dura de lobo a Eagan Desollapieles junto a la Abadía de Villanorte.
07) Haz "Eagan Peltskinner" (48.9, 40.2): Habla con Eagan Desollapieles.
08) Haz "Report to Goldshire" (42.1, 65.9): Lleva los documentos del alguacil McBride al alguacil Dughan a Villadorada.
09) Entrega "A Threat Within" y "Kobold Camp Cleanup" y "Investigate Echo Ridge" y "Skirmish at Echo Ridge" a Alguacil McBride (48.9, 41.6).
10) Entrega "Wolves Across the Border" y "Eagan Peltskinner" a Eagan Desollapelambres (48.9, 40.2).
11) Entrega "Report to Goldshire" a Alguacil Dughan (42.1, 65.9).
]], }
SKquests_GuideES.Alliance[2] = {title = [[2-5 Northshire Valley — Circuito 2]], text = [[
01) Toma estas 5 misiones cerca de Ayudante de alguacil Willem (48.2, 42.9): "Brotherhood of Thieves", "Milly Osworth", "Milly's Harvest", "Grape Manifest", "Bounty on Garrick Padfoot".
02) Haz "Brotherhood of Thieves" (48.2, 42.9): Lleva 12 pañuelos de tela de saco rojo al ayudante Willem cerca de la Abadía de Villanorte.
03) Haz "Bounty on Garrick Padfoot" (48.2, 42.9): Mata a Garrick Piesuaves y lleva su cabeza al ayudante Willem a la Abadía de Villanorte.
04) Haz "Grape Manifest" (49.5, 41.6): Lleva el Informe de la vendimia al hermano Neals a la Abadía de Villanorte.
05) Haz "Milly Osworth" (50.7, 39.3): Habla con Milly Osworth.
06) Haz "Milly's Harvest" (50.7, 39.3): Lleva 8 cajas de uva recogida a Milly Osworth a la Abadía de Villanorte.
07) Entrega "Brotherhood of Thieves" y "Bounty on Garrick Padfoot" a Ayudante de alguacil Willem (48.2, 42.9).
08) Entrega "Milly Osworth" y "Milly's Harvest" a Milly Osworth (50.7, 39.3).
09) Entrega "Grape Manifest" a Hermano Neals (49.5, 41.6).
]], }
