SKquests_GuideES.Alliance[5] = {title = [[5-10 Elwynn Forest — Circuito 1]], text = [[
01) Toma estas 7 misiones cerca de William Mortero (43.3, 65.7): "Collecting Kelp", "The Escape", "Westbrook Garrison Needs Help!", "Further Concerns", "A Fishy Peril", "Cloth and Leather Armor", "Manhunt".
02) Haz "Collecting Kelp" (43.3, 65.7): Lleva 4 hojas de kelp cristalino William Mortero a Villadorada.
03) Haz "A Fishy Peril" (42.1, 65.9): Remy Dos Veces quiere que hables con el alguacil Dughan de Villadorada.
04) Haz "Manhunt" (42.1, 65.9): Encuentra y mata al Coleccionista y vuelve junto al alguacil Dughan con la sortija de coleccionista.
05) Haz "Westbrook Garrison Needs Help!" (24.2, 74.4): Ve al Cuartel de Arroyoeste y habla con el ayudante del alguacil Rainer.
06) Haz "The Escape" (43.2, 89.6): Lleva el licor de invisibilidad a Maybell Maclure.
07) Haz "Further Concerns" (74.0, 72.2): El alguacil Dughan quiere que hables con el guardia Thomas.
08) Haz "Cloth and Leather Armor" (79.5, 68.8): Entrega a Sara Timberlain el marcador de armaduras de Ventormenta.
09) Entrega "Collecting Kelp" a William Mortero (43.3, 65.7).
10) Entrega "The Escape" a Maybell Maclure (43.2, 89.6).
11) Entrega "Westbrook Garrison Needs Help!" a Ayudante de alguacil Rainer (24.2, 74.4).
12) Entrega "Further Concerns" a Guardia Thomas (74.0, 72.2).
13) Entrega "A Fishy Peril" y "Manhunt" a Alguacil Dughan (42.1, 65.9).
14) Entrega "Cloth and Leather Armor" a Sara Timberlain (79.5, 68.8).
]], }
