04) Haz "The Path of the Righteous" (49.5, 36.4): Lleva 200 trozos de caparazón de silítido a Baristolth.
05) Haz "The Hand of the Righteous" (49.5, 36.4): Lleva 200 trozos de caparazón de silítido a Baristolth.
