08) Haz "Twilight Geolords" (20.7, 88.4): Mata 10 geoseñores Crepusculares y, a continuación, ve a ver a Huum Ferocrín en el Fuerte Cenarion.
09) Entrega "A Humble Offering" a Aurel Hojaurea (52.0, 38.2).
10) Entrega "What Tomorrow Brings" y "The Path of the Righteous" y "The Hand of the Righteous" a Baristolth del Mar de Dunas (49.5, 36.4).
11) Entrega "Anachronos" a Anacronos (65.2, 50.0).
12) Entrega "Twilight Geolords" y "Vyral the Vile" a Huum Ferocrín (48.6, 37.9).
