SKquests_GuideES.Horde[1] = {title = [[1-1 Valley of Trials — Circuito 1]], text = [[
01) Acepta "The New Horde" con Eitrigg (34.3, 39.4).
02) Haz "The New Horde" (42.1, 68.3): Informa a Gornek en El Cubil.
03) Entrega "The New Horde" a Gornek (42.1, 68.3).
]], }
SKquests_GuideES.Horde[2] = {title = [[1-5 Valley of Trials — Circuito 2]], text = [[
01) Toma estas 7 misiones cerca de Kaltunk (43.3, 68.5): "Your Place In The World", "Cutting Teeth", "Sting of the Scorpid", "Galgar's Cactus Apple Surprise", "Sarkoth", "Burning Blade Medallion", "Sarkoth".
02) Haz "Burning Blade Medallion" (42.8, 69.1): Lleva el medallón del Filo Ardiente a Zureetha Vistalonga, a las puertas de El Cubil.
03) Haz "Your Place In The World" (42.1, 68.3): Habla con Gornek. Recuerda que Kaltunk marcó en tu mapa su ubicación y que te mencionó que Gornek...
04) Haz "Cutting Teeth" (42.1, 68.3): Mata a 10 jabalíes jaspeados y vuelve con Gornek en El Cubil.
05) Haz "Sting of the Scorpid" (42.1, 68.3): Consigue 10 colas de trabajador escórpido para Gornek en El Cubil.
06) Haz "Sarkoth" (42.1, 68.3): Informa de la situación de Hana\'zua a Gornek en El Cubil.
07) Haz "Galgar's Cactus Apple Surprise" (42.7, 67.2): Lleva a Galgar 10 manzanas de cactus. Recuerdas haberle oído decir que se encuentran junto a los...
08) Haz "Sarkoth" (40.6, 62.6): Mata a Sarkoth y llévale su zarpa a Hana\'zua.
09) Entrega "Your Place In The World" y "Cutting Teeth" y "Sting of the Scorpid" y "Sarkoth" a Gornek (42.1, 68.3).
10) Entrega "Galgar's Cactus Apple Surprise" a Galgar (42.7, 67.2).
11) Entrega "Sarkoth" a Hana'zua (40.6, 62.6).
12) Entrega "Burning Blade Medallion" a Zureetha Vistalonga (42.8, 69.1).
]], }
SKquests_GuideES.Horde[3] = {title = [[1-5 Valley of Trials — Circuito 3]], text = [[
01) Toma estas 4 misiones cerca de Zureetha Vistalonga (42.8, 69.1): "Report to Sen'jin Village", "Vile Familiars", "Lazy Peons", "Thazz'ril's Pick".
02) Haz "Vile Familiars" (42.8, 69.1): Mata a 12 familiares viles. Vuelve con Zureetha Vistalonga a las puertas de El Cubil.
03) Haz "Lazy Peons" (44.6, 68.7): Utiliza la Cachiporra del supervisor con los peones vagos que estén durmiendo. Despierta a 5 peones...
04) Haz "Thazz'ril's Pick" (44.6, 68.7): Lleva el pico de Thazz\'ril al supervisor Thazz\'ril.
05) Haz "Report to Sen'jin Village" (55.9, 74.7): Habla con el maestro Gadrin en Poblado Sen\'jin.
06) Entrega "Report to Sen'jin Village" a Maestro Gadrin (55.9, 74.7).
07) Entrega "Vile Familiars" a Zureetha Vistalonga (42.8, 69.1).
08) Entrega "Lazy Peons" y "Thazz'ril's Pick" a Supervisor Thazz'ril (44.6, 68.7).
]], }
SKquests_GuideES.Horde[4] = {title = [[1-1 Valley of Trials — Circuito 4]], text = [[
01) Acepta "Welcome!" con el dador.
02) Haz "Welcome!" (43.0, 69.4): Lleva el vale regalo del Valle de los Retos a Magga.
03) Entrega "Welcome!" a Magga (43.0, 69.4).
]], }
SKquests_GuideES.Horde[5] = {title = [[4-13 Durotar — Circuito 1]], text = [[
01) Toma estas 2 misiones cerca de Neeru Hojafuego (49.5, 50.6): "Ak'Zeloth", "Finding the Antidote".
02) Haz "Finding the Antidote" (47.2, 53.6): Lleva 4 glándulas de veneno de venocola a Kor\'ghan a Orgrimmar.
03) Haz "Ak'Zeloth" (62.3, 20.1): Habla con Ak\'Zeloth en Los Baldíos.
04) Entrega "Ak'Zeloth" a Ak'Zeloth (62.3, 20.1).
05) GUARDA "Finding the Antidote" en el registro — la entregarás luego en Orgrimmar (viaje agrupado).
]], }
SKquests_GuideES.Horde[6] = {title = [[4-12 Durotar — Circuito 2]], text = [[
01) Toma estas 6 misiones cerca de Furl Ceñosprecio (49.9, 40.4): "Carry Your Weight", "Dark Storms", "Margoz", "Break a Few Eggs", "Encroachment", "Conscript of the Horde".
02) Haz "Carry Your Weight" (49.9, 40.4): Furl Ceñosprecio de la Atalaya de Cerrotajo quiere 8 retales.
03) Haz "Break a Few Eggs" (51.1, 42.4): Lleva 3 huevos de colazote al cocinero Torka de Cerrotajo.
04) Haz "Dark Storms" (52.2, 43.2): Lleva la zarpa de Fizzle a Orgnil Escaralma a Cerrotajo.
05) Haz "Encroachment" (42.8, 52.6): Mata a 4 jabaespines Crines de Acero, 4 rastreadores Crines de Acero, 4 correpolvos Crines de Acero...
06) Haz "Margoz" (56.4, 20.0): Habla con Margoz.
07) Haz "Conscript of the Horde" (62.3, 19.4): Sigue la carretera occidental de Cerrotajo a Los Baldíos. Pasa el puente. Detente en la avanzada...
08) Entrega "Carry Your Weight" a Furl Ceñosprecio (49.9, 40.4).
09) Entrega "Dark Storms" a Orgnil Escaralma (52.2, 43.2).
10) Entrega "Margoz" a Margoz (56.4, 20.0).
11) Entrega "Break a Few Eggs" a Cocinero Torka (51.1, 42.4).
12) Entrega "Encroachment" a Gar'Thok (51.9, 43.5).
13) Entrega "Conscript of the Horde" a Kargal Marca de Guerra (62.3, 19.4).
14) CONSEJO: Guarda en el banco los [Paño de lino] que caigan aquí (~30% drop) — los pedirá "Mending Old Wounds" (nv ~15, The Barrens).
]], }
SKquests_GuideES.Horde[7] = {title = [[4-14 Durotar — Circuito 3]], text = [[
01) Toma estas 4 misiones cerca de Margoz (56.4, 20.0): "Skull Rock", "Neeru Fireblade", "The Demon Seed", "Crossroads Conscription".
02) Haz "Skull Rock" (56.4, 20.0): Recoge los collares ardientes de los fieles de Roca del Cráneo. Llévaselos a Margoz a su campamento.
03) Haz "The Demon Seed" (62.3, 20.1): Coge 1 piedra de energía imperfecta. Llévalo al Altar de Fuego antes de caduque la piedra y vuelve...
04) Haz "Crossroads Conscription" (52.2, 31.0): Sigue la carretera occidental desde la Avanzada de Kargath . Gira a la izquierda en la intersección...
05) Haz "Neeru Fireblade" (49.5, 50.6): Lleva un collar de muestra a Neeru Hojafuego a Orgrimmar.
06) Entrega "Skull Rock" a Margoz (56.4, 20.0).
07) Entrega "The Demon Seed" a Ak'Zeloth (62.3, 20.1).
08) Entrega "Crossroads Conscription" a Sergra Espinoscura (52.2, 31.0).
09) GUARDA "Neeru Fireblade" en el registro — la entregarás luego en Orgrimmar (viaje agrupado).
]], }
