05) Haz "Supplying the Sepulcher" (45.6, 42.6): Lleva el pedido de Podrig a Karos Razok.
06) Haz "Ride to the Undercity" (61.5, 41.8): Compra un viaje en murciélago a Entrañas al maestro de murciélagos Karos Razok. Después lleva el...
07) Haz "Lost Deathstalkers" (53.5, 13.4): Encuentra a los Mortacechadores Quinn y Rane Yorick.
08) Haz "Return to Quinn" (53.4, 12.6): Lleva la poción de Quinn a Quinn Yorick en Los Dominios de Ivar, al norte de El Sepulcro.
09) Entrega "Supplying the Sepulcher" a Karos Razok (45.6, 42.6).
10) Entrega "Return to Quinn" a Quinn Yorick (53.4, 12.6).
11) Entrega "Lost Deathstalkers" a Rane Yorick (53.5, 13.4).
