13) Entrega "The Dead Fields" a Sumo ejecutor Hadrec (43.4, 40.9).
14) Entrega "Border Crossings" a Cajón de Dalaran.
15) GUARDA "Ride to the Undercity" en el registro — la entregarás luego en Entrañas (viaje agrupado).
]], }
SKquests_GuideES.Horde[69] = {title = [[10-17 Silverpine Forest — Circuito 2]], text = [[
