SKquests_GuideES.Horde[120] = {title = [[20-30 Hillsbrad Foothills — Circuito 1]], text = [[
01) Toma estas 7 misiones cerca de Guardia de la Muerte Samsa (60.9, 81.4): "Souvenirs of Death", "Elixir of Pain", "Elixir of Pain", "Elixir of Agony", "Elixir of Agony", "Elixir of Agony", "Elixir of Agony".
02) Haz "Souvenirs of Death" (60.9, 81.4): El guardia de la muerte Samsa de Molino Tarren quiere 10 calaveras humanas de Trabalomas.
03) Haz "Elixir of Pain" (60.1, 80.7): Lleva 10 viales de sangre de puma al boticario Lydon de Molino Tarren.
04) Haz "Elixir of Agony" (60.1, 80.7): Lleva 6 flores de morrobarro al boticario Lydon de Molino Tarren.
05) Haz "Elixir of Agony" (60.1, 80.7): Lleva un barril de cerveza Machacacanillas al boticario Lydon de Molino Tarren.
06) Haz "Elixir of Agony" (60.1, 80.7): Coloca el barril contaminado en la alfombra para los granjeros.
07) Haz "Elixir of Agony" (48.8, 69.3): Lleva el compuesto de morrobarro al maestro boticario Faranell a Entrañas.
08) Haz "Elixir of Pain" (27.2, 99.3): Dale el elixir del dolor a Stanley.
09) Entrega "Souvenirs of Death" a Guardia de la Muerte Samsa (60.9, 81.4).
10) Entrega "Elixir of Pain" y "Elixir of Agony" y "Elixir of Agony" a Boticario Lydon (60.1, 80.7).
11) Entrega "Elixir of Pain" a Filoja (27.2, 99.3).
12) Entrega "Elixir of Agony" a Alfombra polvorienta.
13) GUARDA "Elixir of Agony" en el registro — la entregarás luego en Entrañas (viaje agrupado).
]], }
SKquests_GuideES.Horde[121] = {title = [[26-42 Hillsbrad Foothills — Circuito 2]], text = [[
01) Toma estas 7 misiones cerca de Guardia de la Muerte Humbert (61.6, 82.0): "Humbert's Sword", "Helcular's Revenge", "Helcular's Revenge", "Infiltration", "Gol'dir", "Lord Aliden Perenolde", "Stone Tokens".
02) Haz "Humbert's Sword" (61.6, 82.0): Recoge la espada del Guardia de la Muerte Humbert en Dun Garok y llévasela a Molino Tarren.
03) Haz "Infiltration" (62.2, 82.5): Consigue información sobre el paradero de Gol\'dir\'s e informa a Krusk en Molino Tarren.
04) Haz "Helcular's Revenge" (62.9, 81.4): Róbale la Vara de Helcular a los yetis y llévasela al novicio Thaivand a Molino Tarren.
05) Haz "Stone Tokens" (60.2, 82.9): Lleva 10 muestras de piedra gastada al guardián Bel’varil de Molino Tarren.
06) Haz "Gol'dir" (60.0, 43.7): Libera a Gol\'dir e informa a Krusk en Molino Tarren.
