08) Haz "Lord Aliden Perenolde" (39.3, 14.3): Mata a Aliden Perenolde y pregunta a su querida, Elysa, por el colgante de Taretha.
09) Entrega "Humbert's Sword" a Guardia de la Muerte Humbert (61.6, 82.0).
10) Entrega "Helcular's Revenge" a Novicio Thaivand (62.9, 81.4).
11) Entrega "Helcular's Revenge" a Tumba de Helcular (56.1, 28.4).
12) Entrega "Infiltration" a Krusk (62.2, 82.5).
13) Entrega "Gol'dir" a Gol'dir (60.0, 43.7).
14) Entrega "Lord Aliden Perenolde" a Elysa (39.3, 14.3).
15) Entrega "Stone Tokens" a Vigilante Bel'varil (60.2, 82.9).
16) CONSEJO: Guarda en el banco los [Tela de paño mágico] que caigan aquí (~3% drop) — los pedirá "War at Sea" (nv ~40, Tanaris).
]], }
